        case ImageAsset::CloseWallLeft: return &kCloseWallLeftAsset;
        case ImageAsset::CloseWallLeft2: return &kCloseWallLeft2Asset;
        case ImageAsset::CloseWallRight: return &kCloseWallRightAsset;
        case ImageAsset::CloseWallRight2: return &kCloseWallRight2Asset;
        case ImageAsset::EnemyRatIconMed: return &kEnemyRatIconMedAsset;
        case ImageAsset::EnemyRatIconSmall: return &kEnemyRatIconSmallAsset;
        case ImageAsset::EnemySkeletonIconMed: return &kEnemySkeletonIconMedAsset;
        case ImageAsset::EnemySkeletonIconSmall: return &kEnemySkeletonIconSmallAsset;
